# Artifacts for DataVault (Java)

Below you will find the standalone web dashboard (`index.html`) and the complete project documentation (`README.md`).

---

## 1. `index.html` (Interactive Web Dashboard)

Save this file as `index.html`. It provides a clean, responsive single-page user interface with search, category filtering, and record management.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>DataVault - Embedded Data Management</title>
  <style>
    :root {
      --bg-color: #0f172a;
      --card-bg: #1e293b;
      --border: #334155;
      --text-main: #f8fafc;
      --text-muted: #94a3b8;
      --accent: #38bdf8;
      --accent-hover: #0284c7;
      --danger: #ef4444;
      --danger-hover: #dc2626;
      --tag-bg: #0369a1;
    }

    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    }

    body {
      background-color: var(--bg-color);
      color: var(--text-main);
      padding: 2rem 1rem;
      display: flex;
      justify-content: center;
    }

    .container {
      width: 100%;
      max-width: 1000px;
    }

    header {
      margin-bottom: 2rem;
      border-bottom: 1px solid var(--border);
      padding-bottom: 1rem;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }

    h1 {
      font-size: 1.75rem;
      color: var(--accent);
    }

    .badge {
      background: var(--tag-bg);
      color: #fff;
      font-size: 0.8rem;
      padding: 0.25rem 0.6rem;
      border-radius: 9999px;
    }

    .card {
      background: var(--card-bg);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 1.5rem;
      margin-bottom: 1.5rem;
    }

    .card h2 {
      font-size: 1.2rem;
      margin-bottom: 1rem;
      color: var(--text-main);
    }

    .form-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1rem;
    }

    .form-group-full {
      grid-column: span 2;
    }

    label {
      display: block;
      font-size: 0.85rem;
      color: var(--text-muted);
      margin-bottom: 0.4rem;
    }

    input, textarea, select {
      width: 100%;
      padding: 0.65rem;
      background: #0f172a;
      border: 1px solid var(--border);
      color: #fff;
      border-radius: 6px;
      font-size: 0.9rem;
    }

    textarea {
      resize: vertical;
      min-height: 80px;
    }

    input:focus, textarea:focus {
      outline: 1px solid var(--accent);
    }

    button {
      cursor: pointer;
      border: none;
      border-radius: 6px;
      padding: 0.65rem 1.2rem;
      font-weight: 600;
      transition: background 0.2s;
    }

    .btn-primary {
      background: var(--accent);
      color: #0f172a;
      margin-top: 1rem;
    }

    .btn-primary:hover {
      background: var(--accent-hover);
    }

    .btn-danger {
      background: var(--danger);
      color: #fff;
      padding: 0.35rem 0.75rem;
      font-size: 0.8rem;
    }

    .btn-danger:hover {
      background: var(--danger-hover);
    }

    .search-bar {
      margin-bottom: 1.5rem;
      display: flex;
      gap: 1rem;
    }

    table {
      width: 100%;
      border-collapse: collapse;
      text-align: left;
    }

    th, td {
      padding: 0.85rem;
      border-bottom: 1px solid var(--border);
      font-size: 0.9rem;
    }

    th {
      color: var(--text-muted);
      text-transform: uppercase;
      font-size: 0.75rem;
    }

    .code-preview {
      font-family: monospace;
      color: #38bdf8;
      max-width: 250px;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    .category-tag {
      background: #334155;
      padding: 0.2rem 0.5rem;
      border-radius: 4px;
      font-size: 0.75rem;
      text-transform: uppercase;
    }
  </style>
</head>
<body>
  <div class="container">
    <header>
      <div>
        <h1>DataVault Web Portal</h1>
        <p style="color: var(--text-muted); font-size: 0.9rem;">Local Storage & Document Inspector</p>
      </div>
      <span class="badge" id="record-count">0 Records</span>
    </header>

    <!-- Store / Update Form -->
    <div class="card">
      <h2>Store / Update Data</h2>
      <form id="vault-form">
        <div class="form-grid">
          <div>
            <label for="key">Unique Key</label>
            <input type="text" id="key" required placeholder="e.g., config.theme, user:42" />
          </div>
          <div>
            <label for="category">Category</label>
            <input type="text" id="category" placeholder="general" />
          </div>
          <div class="form-group-full">
            <label for="value">Value (Plain text or JSON Object/Array)</label>
            <textarea id="value" required placeholder='{"active": true, "roles": ["admin"]}'></textarea>
          </div>
        </div>
        <button type="submit" class="btn-primary">Save to Vault</button>
      </form>
    </div>

    <!-- Search & Filter Area -->
    <div class="search-bar">
      <input type="text" id="search-input" placeholder="Search across keys, values, and categories..." />
    </div>

    <!-- Data Table -->
    <div class="card">
      <h2>Stored Records</h2>
      <div style="overflow-x: auto;">
        <table>
          <thead>
            <tr>
              <th>Key</th>
              <th>Category</th>
              <th>Value</th>
              <th>Last Updated</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody id="table-body">
            <!-- Populated via JavaScript -->
          </tbody>
        </table>
      </div>
    </div>
  </div>

  <script>
    const STORAGE_KEY = "datavault_local_db";

    function getVaultData() {
      const raw = localStorage.getItem(STORAGE_KEY);
      return raw ? JSON.parse(raw) : [];
    }

    function saveVaultData(data) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
      render();
    }

    document.getElementById("vault-form").addEventListener("submit", (e) => {
      e.preventDefault();
      const key = document.getElementById("key").value.trim();
      const category = document.getElementById("category").value.trim() || "general";
      const value = document.getElementById("value").value.trim();
      const now = new Date().toISOString();

      let items = getVaultData();
      const existingIndex = items.findIndex((i) => i.key === key);

      if (existingIndex > -1) {
        items[existingIndex].value = value;
        items[existingIndex].category = category.toLowerCase();
        items[existingIndex].updated_at = now;
      } else {
        items.push({
          key,
          value,
          category: category.toLowerCase(),
          created_at: now,
          updated_at: now,
        });
      }

      saveVaultData(items);
      document.getElementById("vault-form").reset();
    });

    function deleteItem(key) {
      if (confirm(`Delete key "${key}"?`)) {
        let items = getVaultData().filter((i) => i.key !== key);
        saveVaultData(items);
      }
    }

    function render(searchQuery = "") {
      const tbody = document.getElementById("table-body");
      const countBadge = document.getElementById("record-count");
      const items = getVaultData();

      const filtered = items.filter((item) => {
        const q = searchQuery.toLowerCase();
        return (
          item.key.toLowerCase().includes(q) ||
          item.category.toLowerCase().includes(q) ||
          item.value.toLowerCase().includes(q)
        );
      });

      countBadge.textContent = `${items.length} Record(s)`;
      tbody.innerHTML = "";

      if (filtered.length === 0) {
        tbody.innerHTML = `<tr><td colspan="5" style="text-align:center; color: var(--text-muted);">No records found.</td></tr>`;
        return;
      }

      filtered.forEach((item) => {
        const tr = document.createElement("tr");
        tr.innerHTML = `
          <td><strong>${item.key}</strong></td>
          <td><span class="category-tag">${item.category}</span></td>
          <td><div class="code-preview" title="${item.value.replace(/"/g, '&quot;')}">${item.value}</div></td>
          <td style="color: var(--text-muted); font-size: 0.8rem;">${new Date(item.updated_at).toLocaleString()}</td>
          <td><button class="btn-danger" onclick="deleteItem('${item.key}')">Delete</button></td>
        `;
        tbody.appendChild(tr);
      });
    }

    document.getElementById("search-input").addEventListener("input", (e) => {
      render(e.target.value.trim());
    });

    render();
  </script>
</body>
</html>
```

